class PswDataEntryPage extends StatefulWidget {
  const PswDataEntryPage({super.key});
  
  @override
  State<PswDataEntryPage> createState() => _PswDataEntryPageState();
}

class _PswDataEntryPageState extends State<PswDataEntryPage> {
  String _searchQuery = '';

  @override
  Widget build(BuildContext context) {
    final formIds = GeneratedSchemas.schemas.keys.toList()
      ..sort()
      ..retainWhere((id) => id.toLowerCase().contains(_searchQuery.toLowerCase()));

    return Scaffold(
      backgroundColor: const Color(0xFF0F172A),
      appBar: AppBar(
        title: Text('Database Matrix', style: GoogleFonts.outfit(fontWeight: FontWeight.bold, color: Colors.white)),
        backgroundColor: Colors.transparent,
        elevation: 0,
        centerTitle: true,
        iconTheme: const IconThemeData(color: Colors.white),
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 16),
            child: TextField(
              style: const TextStyle(color: Colors.white),
              decoration: InputDecoration(
                filled: true,
                fillColor: const Color(0xFF1E293B),
                hintText: 'Search ${GeneratedSchemas.schemas.length} Data Tables...',
                hintStyle: const TextStyle(color: Colors.white54),
                prefixIcon: const Icon(Icons.search, color: Colors.blueAccent),
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(16), borderSide: BorderSide.none),
              ),
              onChanged: (val) => setState(() => _searchQuery = val),
            ),
          ),
          Expanded(
            child: GridView.builder(
              padding: const EdgeInsets.all(24),
              gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(
                maxCrossAxisExtent: 280,
                childAspectRatio: 1.2,
                crossAxisSpacing: 20,
                mainAxisSpacing: 20,
              ),
              itemCount: formIds.length,
              itemBuilder: (context, index) {
                final formId = formIds[index];
                return _buildModernTile(context, formId);
              },
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildModernTile(BuildContext context, String formId) {
    return Container(
      decoration: BoxDecoration(
        color: const Color(0xFF1E293B),
        borderRadius: BorderRadius.circular(24),
        boxShadow: const [
          BoxShadow(
            color: Colors.black45,
            blurRadius: 15,
            offset: Offset(0, 8),
          )
        ],
      ),
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          borderRadius: BorderRadius.circular(24),
          splashColor: Colors.blueAccent.withOpacity(0.2),
          highlightColor: Colors.blueAccent.withOpacity(0.1),
          onTap: () {
            Navigator.of(context).push(
              MaterialPageRoute(
                builder: (_) => Scaffold(
                  backgroundColor: const Color(0xFF0F172A),
                  appBar: AppBar(
                    title: Text('$formId Record', style: GoogleFonts.outfit(color: Colors.white)),
                    backgroundColor: Colors.transparent,
                    elevation: 0,
                    iconTheme: const IconThemeData(color: Colors.white),
                  ),
                  body: PrimeCareDynamicFormBuilder(
                    formId: formId,
                    apiGet: (path) async {
                      await Future.delayed(const Duration(milliseconds: 300));
                      // Inject perfectly parsed Prisma table architecture
                      return GeneratedSchemas.schemas[formId] ?? {
                        'title': 'Error', 
                        'fields': [], 
                        'submitEndpoint': '/err'
                      };
                    },
                    apiPost: (path, data) async {
                      await Future.delayed(const Duration(milliseconds: 600));
                      print('MOCK API EDGE POST => $path DATA: $data');
                    },
                  ),
                ),
              ),
            );
          },
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                const Icon(Icons.table_chart_rounded, size: 48, color: Colors.blueAccent),
                const SizedBox(height: 16),
                Text(
                  formId,
                  textAlign: TextAlign.center,
                  maxLines: 2,
                  style: GoogleFonts.inter(
                    color: Colors.white,
                    fontWeight: FontWeight.bold,
                    fontSize: 16,
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

